function renderAudioBars(canvasId, bars = 16) {
  const c = document.getElementById(canvasId); if (!c) return;
  const ctx = c.getContext('2d');
  function frame() {
    ctx.clearRect(0,0,c.width,c.height);
    const barWidth = (c.width / bars) - 3;
    for(let i=0; i<bars; i++) {
      const h = (Math.sin(Date.now() * 0.005 + i) * 0.5 + 0.5) * (c.height - 10) + 5;
      ctx.fillStyle = '#10b981';
      ctx.fillRect(i * (barWidth + 3), c.height - h, barWidth, h);
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

